<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick,watch,provide} from 'vue'
import {VueFlow,useVueFlow} from '@vue-flow/core'
import {Background} from '@vue-flow/background'
import FlowNode from './FlowNode.vue'
const clone=v=>JSON.parse(JSON.stringify(v))
const labels=ref({}),defaults=ref({}),catalog=ref(null),base=ref(null),nodes=ref([]),edges=ref([]),snapshot=ref(null),pinned=ref(null)
const modelSamples=ref({}),modelChoice=ref('p08.openai.text');const approvalDetails=ref([]);const search=ref(''),error=ref(''),notice=ref(''),connection=ref('正在连接'),busy=ref(false),saved=ref(false),name=ref('workbench'),tab=ref('overview'),events=ref([]),picking=ref(null),fileInput=ref(null)
const history=ref([]),future=ref([]),left=ref(true),right=ref(true),bottom=ref(true),compact=ref(false),lw=ref(220),rw=ref(300),bh=ref(180),restored=ref(false)
const {fitView,zoomIn,zoomOut,screenToFlowCoordinate,viewport,updateNodeInternals,getSelectedNodes,getNodes,removeSelectedNodes,addSelectedNodes}=useVueFlow()
let narrow=false,normalPanels=null;function responsive(){if(innerWidth<1150&&!narrow){normalPanels={left:left.value,right:right.value};left.value=false;right.value=false;narrow=true}else if(innerWidth>=1150&&narrow){left.value=normalPanels.left;right.value=normalPanels.right;narrow=false}};let pendingFit=true; let sampleDoc=null,approvalDoc=null,pollHandle=null,stopped=false,requestTail=Promise.resolve(),eventsAfter=0
const statusNames={'queued':'等待依赖','running':'运行中','succeeded':'完成','failed':'失败','cancelled':'已取消','waiting-approval':'等待审批','cancel-requested':'取消中','skipped':'已跳过','unknown':'结果未知'}
const icons={'queued':'○','running':'◌','succeeded':'✓','failed':'×','cancelled':'■','waiting-approval':'◇','unknown':'?','skipped':'↷','cancel-requested':'◼'}
function labelState(s){return (icons[s]||'—')+' '+(statusNames[s]||'待运行')}
function def(t,v='0.1.0'){return catalog.value?.nodeDefinitions.find(d=>d.typeId===t&&d.version===v)}
function ports(n){const known=def(n.typeId,n.typeVersion);if(known)return known.ports.filter(p=>p.channel==='data');const found=new Map();for(const e of base.value?.graph.edges||[]){if(e.from.node===n.id)found.set('o'+e.from.port,{id:e.from.port,direction:'output',type:{name:'未知端口'}});if(e.to.node===n.id)found.set('i'+e.to.port,{id:e.to.port,direction:'input',type:{name:'未知端口'}})}return [...found.values()]}
function definition(){if(!base.value)return null;const w=clone(base.value);w.graph.nodes=w.graph.nodes.filter(n=>nodes.value.some(f=>f.id===n.id));w.graph.edges=edges.value.map(e=>({...clone(e.data?.original||{}),id:e.id,kind:'data',from:{node:e.source,port:e.sourceHandle},to:{node:e.target,port:e.targetHandle},order:e.data?.original?.order||0}));return w}
function document(){return {workflow:definition(),layout:{version:'aos-layout/0.1',positions:Object.fromEntries(nodes.value.map(n=>[n.id,{x:n.position.x,y:n.position.y}]))}}}
function nodeChanges(changes){for(const c of changes){const n=nodes.value.find(n=>n.id===c.id);if(n&&c.type==="select")n.selected=c.selected;if(n&&c.type==="position"&&c.position)n.position={...c.position}}}
function edgeChanges(changes){for(const c of changes){const e=edges.value.find(e=>e.id===c.id);if(e&&c.type==="select")e.selected=c.selected}}
function capture(){if(base.value){history.value.push(document());if(history.value.length>80)history.value.shift();future.value=[]}}
function touch(){base.value.version={revision:'draft-'+crypto.randomUUID().slice(0,12)};saved.value=false;error.value='';notice.value='草稿已修改'}
function applyDoc(d){removeSelectedNodes(getSelectedNodes.value);pendingFit=true;base.value=clone(d.workflow);nodes.value=d.workflow.graph.nodes.map(n=>({id:n.id,type:'aos',position:clone(d.layout?.positions[n.id]||{x:0,y:0}),data:{}}));edges.value=d.workflow.graph.edges.map(e=>({id:e.id,source:e.from.node,sourceHandle:e.from.port,target:e.to.node,targetHandle:e.to.port,data:{original:clone(e)}}));saved.value=false;nextTick(()=>{updateNodeInternals();setTimeout(()=>fitView({padding:.06,maxZoom:1}),80)})}
function undo(){if(!history.value.length)return;future.value.push(document());applyDoc(history.value.pop());notice.value='已撤销'}
function redo(){if(!future.value.length)return;history.value.push(document());applyDoc(future.value.pop());notice.value='已重做'}
const selected=computed(()=>base.value?.graph.nodes.find(n=>getSelectedNodes.value.some(f=>f.id===n.id)))
const selectedCount=computed(()=>getSelectedNodes.value.length)
const fields=computed(()=>{const d=selected.value&&def(selected.value.typeId,selected.value.typeVersion);return Object.entries(d?.configSchema?.properties||{})})
const palette=computed(()=>Object.entries(labels.value).sort((a,b)=>['synth.source','synth.step','p07.model','p07.echo-args','tool.mcp.echo_text','p07.echo-text','synth.output','p07.effect-args','tool.mcp.simulated_effect','p07.effect-text'].indexOf(a[0])-['synth.source','synth.step','p07.model','p07.echo-args','tool.mcp.echo_text','p07.echo-text','synth.output','p07.effect-args','tool.mcp.simulated_effect','p07.effect-text'].indexOf(b[0])).filter(([k,v])=>(k+' '+v).toLowerCase().includes(search.value.toLowerCase())))
const approvals=computed(()=>Object.values(snapshot.value?.approvals||{}).filter(a=>a.status==='pending').map(a=>({...a,...approvalDetails.value.find(d=>d.id===a.id&&d.fingerprint===a.fingerprint)})))
const terminal=computed(()=>['succeeded','failed','cancelled','unknown'].includes(snapshot.value?.state))
const canRun=computed(()=>connection.value==='C1 已连接'&&(!snapshot.value||terminal.value)&&snapshot.value?.state!=='unknown'&&!busy.value)
const problems=computed(()=>Object.values(snapshot.value?.nodes||{}).filter(n=>n.error).map(n=>({id:n.nodeId||n.key,message:n.error.code})))
const result=computed(()=>snapshot.value?.scopes?.main?.result)
const style=computed(()=>({'--left':left.value?lw.value+'px':'0px','--right':right.value?rw.value+'px':'0px','--bottom':bottom.value?bh.value+'px':'0px'}))
function nodeData(id){const i=nodes.value.findIndex(f=>f.id===id);const n=base.value.graph.nodes.find(n=>n.id===id);const r=snapshot.value?.nodes['main/'+id];const old=pinned.value?.graph.nodes.find(n=>n.id===id);return {spec:n,ports:ports(n),label:labels.value[n.typeId]||'未知节点 · '+n.typeId,ordinal:String(i+1).padStart(2,'0'),symbol:n.typeId.startsWith('tool.')?'⌁':n.typeId==='p07.model'?'◇':n.typeId.startsWith('synth.output')?'↗':'▤',preview:preview(n),state:r?.state||'',status:labelState(r?.state),badge:n.typeId==='p07.model'?'MOCK':n.typeId.startsWith('tool.')?'MCP':'',edited:old&&JSON.stringify(old)!==JSON.stringify(n)}}
provide('aos-graph',{nodeData})
function preview(n){return n.config.value||n.config.suffix||(n.typeId==='p07.model'?`${n.config.maxOutputTokens} 字符 · ${n.config.delayMs} ms`:n.config.operation||(!def(n.typeId,n.typeVersion)?'缺少兼容描述，禁止执行':'严格类型连接'))}
// Only transport reads are polled. Every displayed business state comes from C1.
function api(op,body={}){const id='ui-'+crypto.randomUUID();const task=requestTail.catch(()=>{}).then(async()=>{if(!window.__TAURI__?.core)throw Error('真实 Tauri 桥不可用');const r=await window.__TAURI__.core.invoke('host_request',{request:{v:'aos-local/0.1',kind:'request',id,op,body}});if(!r.ok)throw Error(r.error.code);return r.result});requestTail=task;return task}
async function action(fn){error.value='';busy.value=true;try{return await fn()}catch(e){error.value=String(e.message||e);tab.value='problems'}finally{busy.value=false}}
async function validate(){return action(async()=>{const r=await api('load',{action:'validate',workflow:definition()});notice.value='C1 契约校验通过 · '+r.workflowDigest.slice(0,12);return r})}
async function run(){return action(async()=>{const w=definition();const r=await api('load',{action:'validate',workflow:w});const s=await api('create',{token:r.token});pinned.value=clone(w);snapshot.value=s;events.value=[];eventsAfter=0;notice.value='已固定运行修订 '+s.workflowRevision;tab.value='overview'})}
async function save(){return action(async()=>{await api('load',{action:'save',name:name.value,document:document()});saved.value=true;notice.value='已保存 · '+name.value})}
async function open(){return action(async()=>{const d=await api('load',{action:'open',name:name.value});capture();applyDoc(d);saved.value=true;notice.value='已重新加载 · '+name.value})}
async function cancel(){return action(async()=>{snapshot.value=await api('cancel');notice.value='已请求取消，等待 C1 确认'})}
async function decide(a,decision){return action(async()=>{snapshot.value=await api('approve',{approvalId:a.id,fingerprint:a.fingerprint,decision});notice.value=decision?'批准已提交，C1 核验后派发':'已拒绝'})}
async function poll(){if(stopped)return;try{if(snapshot.value){const s=await api('status');if(s.runId===snapshot.value.runId){snapshot.value=s;if(Object.values(s.approvals).some(a=>a.status==='pending'))approvalDetails.value=await api('approvals');else approvalDetails.value=[];const batch=await api('events',{after:eventsAfter});if(batch.runId===s.runId){for(const e of batch.events){if(e.seq>eventsAfter){events.value.push(e);eventsAfter=e.seq}}}if(events.value.length>500)events.value=events.value.slice(-500)}}}catch(e){connection.value='执行器断连 · 结果待核实';error.value='IPC：'+e.message;tab.value='problems'}finally{if(!stopped)pollHandle=setTimeout(poll,300)}}
function add(tid,pos){capture();const id='n'+crypto.randomUUID().slice(0,8);const n={id,typeId:tid,typeVersion:'0.1.0',enabled:true,config:clone(defaults.value[tid]||{}),policy:clone(base.value.executionPolicy)};if(tid.startsWith('tool.mcp.')){const name=tid.slice(9);n.adapter={id:'fixture.p04.'+name,version:'0.1.0',capabilityId:'cap.fixture.p04.'+name};n.serviceSlot='tool.'+name}if(def(tid)?.executionKind==='model'){n.adapter={id:'fixture.'+tid,version:'0.1.0',capabilityId:'cap.fixture.'+tid};n.serviceSlot=tid}base.value.graph.nodes.push(n);nodes.value.forEach(n=>n.selected=false);nodes.value.push({id,type:'aos',position:pos||screenToFlowCoordinate({x:window.innerWidth/2,y:window.innerHeight/2}),data:{},selected:true});updateRequirements();touch()}
function updateRequirements(){base.value.environmentRequirements=['echo_text','simulated_effect'].filter(name=>base.value.graph.nodes.some(n=>nodes.value.some(f=>f.id===n.id)&&n.typeId==='tool.mcp.'+name)).map(name=>({slot:'tool.'+name,kind:'service',required:true,adapter:{id:'fixture.p04.'+name,version:'0.1.0',capabilityId:'cap.fixture.p04.'+name},permissions:['synthetic:tool:'+name]}));for(const n of base.value.graph.nodes.filter(n=>def(n.typeId)?.executionKind==='model')){if(!base.value.environmentRequirements.some(r=>r.slot===n.typeId))base.value.environmentRequirements.push({slot:n.typeId,kind:'service',required:true,adapter:clone(n.adapter),permissions:['synthetic:model-http']})}}
function remove(){capture();const selected=new Set(getSelectedNodes.value.map(n=>n.id));nodes.value=nodes.value.filter(n=>!selected.has(n.id));base.value.graph.nodes=base.value.graph.nodes.filter(n=>!selected.has(n.id));edges.value=edges.value.filter(e=>!e.selected&&!selected.has(e.source)&&!selected.has(e.target));updateRequirements();touch()}
function duplicate(){capture();const chosen=nodes.value.filter(n=>getSelectedNodes.value.some(f=>f.id===n.id));const ids=new Map(chosen.map(n=>[n.id,'n'+crypto.randomUUID().slice(0,8)]));for(const n of chosen){const spec=clone(base.value.graph.nodes.find(s=>s.id===n.id));spec.id=ids.get(n.id);base.value.graph.nodes.push(spec);nodes.value.push({...clone(n),id:spec.id,position:{x:n.position.x+32,y:n.position.y+32},selected:true});n.selected=false}for(const e of [...edges.value])if(ids.has(e.source)&&ids.has(e.target))edges.value.push({...clone(e),id:'e'+crypto.randomUUID(),source:ids.get(e.source),target:ids.get(e.target)});updateRequirements();touch()}
function connectionError(c){if(c.source===c.target)return '不能连接到自身';const a=base.value.graph.nodes.find(n=>n.id===c.source),b=base.value.graph.nodes.find(n=>n.id===c.target);if(!a||!b||!def(a.typeId,a.typeVersion)||!def(b.typeId,b.typeVersion))return '未知节点不能建立新的执行连接';const pa=a&&ports(a).find(p=>p.id===c.sourceHandle),pb=b&&ports(b).find(p=>p.id===c.targetHandle);if(!pa||!pb||pa.direction!=='output'||pb.direction!=='input')return '端口方向无效';if(JSON.stringify(pa.type)!==JSON.stringify(pb.type))return '类型不兼容：'+(pa.type.schemaRef||pa.type.name)+' → '+(pb.type.schemaRef||pb.type.name);if(edges.value.some(e=>e.target===c.target&&e.targetHandle===c.targetHandle))return '该输入已有连接，请先删除原连线';const reach=new Set([c.target]);let size;do{size=reach.size;for(const e of edges.value)if(reach.has(e.source))reach.add(e.target)}while(size!==reach.size);return reach.has(c.source)?'连接会形成无界循环':''}
function validConnection(c){if(edges.value.some(e=>e.source===c.source&&e.sourceHandle===c.sourceHandle&&e.target===c.target&&e.targetHandle===c.targetHandle))return true;const reason=connectionError(c);if(reason){error.value=reason;return false}return true}
function connect(c){const reason=connectionError(c);if(reason){error.value=reason;return}capture();edges.value.push({id:'e'+crypto.randomUUID(),...c});touch();picking.value=null}
function setField(key,s,e){capture();let value=s.const!==undefined?s.const:s.type==='boolean'?e.target.checked:['integer','number'].includes(s.type)?(e.target.value===''?null:Number(e.target.value)):e.target.value;selected.value.config[key]=value;touch()}
function drop(e){e.preventDefault();const tid=e.dataTransfer.getData('application/aos-node');if(labels.value[tid])add(tid,screenToFlowCoordinate({x:e.clientX,y:e.clientY}))}
function chooseModel(){capture();applyDoc(clone(modelSamples.value[modelChoice.value]));touch()}
function setBudget(key,e){capture();const v=Number(e.target.value);if(key==='concurrencyLimit')base.value.executionPolicy[key]=v;else base.value.executionPolicy.budget[key]=v;touch()}
function reset(effect=false){capture();applyDoc(clone(effect?approvalDoc:sampleDoc));history.value=[];future.value=[];notice.value=effect?'已载入审批合成场景':'已载入合成场景'}
function resize(which,e){const start=e.clientX,sy=e.clientY,old=which==='left'?lw.value:which==='right'?rw.value:bh.value;const move=ev=>{if(which==='left')lw.value=Math.max(184,Math.min(360,old+ev.clientX-start));else if(which==='right')rw.value=Math.max(272,Math.min(480,old-ev.clientX+start));else bh.value=Math.max(96,Math.min(innerHeight*.5,old-ev.clientY+sy))};const end=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);prefs()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end)}
function resizeKey(which,e){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const d=(e.shiftKey?32:8)*(['ArrowRight','ArrowDown'].includes(e.key)?1:-1);if(which==='left')lw.value=Math.max(184,Math.min(360,lw.value+d));else if(which==='right')rw.value=Math.max(272,Math.min(480,rw.value-d));else bh.value=Math.max(96,Math.min(innerHeight*.5,bh.value-d));prefs()}
function prefs(){localStorage.setItem('aos-p008-view',JSON.stringify({left:left.value,right:right.value,bottom:bottom.value,compact:compact.value,lw:lw.value,rw:rw.value,bh:bh.value}))}
watch([left,right,bottom,compact],prefs)
function shortcut(e){const input=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if(e.ctrlKey&&e.key.toLowerCase()==='s'){e.preventDefault();save();return}if(input)return;if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();if(canRun.value)run()}else if(e.shiftKey&&e.key==='F5'){e.preventDefault();cancel()}else if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}else if(e.ctrlKey&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate()}else if(e.ctrlKey&&e.key.toLowerCase()==='a'){e.preventDefault();addSelectedNodes(getNodes.value)}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove()}else if(e.key==='Home'){e.preventDefault();fitView({padding:.06,maxZoom:1})}else if(e.ctrlKey&&e.key==='b'){e.preventDefault();e.altKey?right.value=!right.value:left.value=!left.value}else if(e.ctrlKey&&e.key==='j'){e.preventDefault();bottom.value=!bottom.value}else if(e.key==='Escape')picking.value=null}
function download(){const blob=new Blob([JSON.stringify(document(),null,2)],{type:'application/json'});const a=window.document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name.value+'.aos.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importFile(e){return action(async()=>{const file=e.target.files[0];if(!file)return;if(file.size>240000)throw Error('文件超过 240 KB');const d=JSON.parse(await file.text());if(!d.workflow?.graph||!Array.isArray(d.workflow.graph.nodes)||!Array.isArray(d.workflow.graph.edges))throw Error('文档结构无效');capture();applyDoc(d);notice.value='已导入草稿，运行前必须通过 C1 校验';e.target.value=''})}
onMounted(async()=>{window.addEventListener('keydown',shortcut);window.addEventListener('resize',responsive);responsive();try{const p=JSON.parse(localStorage.getItem('aos-p008-view')||'null');if(p){for(const [k,r] of Object.entries({left,right,bottom,compact,lw,rw,bh}))if(p[k]!==undefined)r.value=p[k]}}catch{}await action(async()=>{await api('host.start');const h=await api('health');catalog.value=h.catalog;labels.value=h.labels;defaults.value=h.defaults;modelSamples.value=h.modelSamples;sampleDoc=h.sample;approvalDoc=h.approvalSample;applyDoc(sampleDoc);connection.value='C1 已连接';notice.value='受限合成环境 · 不连接收费模型或真实账户';try{const s=await api('recover');snapshot.value=s;pinned.value=await api('load',{action:'run-definition'});applyDoc({workflow:pinned.value,layout:sampleDoc.layout});restored.value=true;notice.value='已恢复原运行 · '+s.runId}catch(e){if(!['RUN_NOT_FOUND','NO_OPEN_RUN'].includes(e.message))notice.value='无可恢复运行：'+e.message}});poll()})
onUnmounted(()=>{stopped=true;clearTimeout(pollHandle);window.removeEventListener('keydown',shortcut);window.removeEventListener('resize',responsive)})
</script>

<template>
<main class="workbench" :class="{'zoom-low':viewport.zoom<.65,'zoom-medium':viewport.zoom<.8}" :style="style" :data-density="compact?'compact':'standard'">
 <header class="titlebar"><div class="brand-mark">A</div><strong>AI Orchestration Studio</strong><span class="crumb">工作台 <span>/</span> P0-08</span><div class="spacer"/><span class="experiment">实验构建 · Graphite</span></header>
 <nav class="toolbar" aria-label="工作流工具栏"><input class="workflow-title" aria-label="工作流标题" v-if="base" v-model="base.title" @change="touch"><span class="dirty">{{saved?'已保存':'草稿'}}</span><div class="tools"><button @click="save" :disabled="busy||!base" title="Ctrl+S">保存</button><button @click="open" :disabled="busy||!catalog">重载</button><button @click="validate" :disabled="busy||!base">校验</button><div class="tool-divider"/><button class="primary" data-testid="run" @click="run" :disabled="!canRun">▶ 运行</button><button data-testid="cancel" @click="cancel" :disabled="!snapshot||terminal||busy">■ 取消</button></div><div class="spacer"/><span class="run-state" :class="snapshot?.state" data-testid="run-state">{{snapshot&&connection!=='C1 已连接'?'? 连接中断 · 待核实':labelState(snapshot?.state)}}</span></nav>
 <div v-if="error" class="error-banner" role="alert"><strong>× {{connection.includes('断连')?'连接中断，以下为最后确认状态。 ':''}}{{error}}</strong><button @click="error=''" aria-label="关闭错误">×</button></div>
 <div v-if="approvals.length" class="approval-banner"><strong>◇ 等待人工审批</strong><span>合成操作尚未派发。请核对下方固定动作。</span><button @click="bottom=true;tab='overview'">查看动作</button></div>
 <div class="workspace">
  <aside class="rail"><button :class="{active:left}" @click="left=!left" title="节点库 Ctrl+B" aria-label="切换节点库">▦</button><button :class="{active:right}" @click="right=!right" title="属性 Ctrl+Alt+B" aria-label="切换属性检查器">≡</button><button :class="{active:bottom}" @click="bottom=!bottom" title="执行区 Ctrl+J" aria-label="切换执行区">⌁</button><div class="spacer"/><button @click="compact=!compact" title="切换显示密度" aria-label="切换密度">{{compact?'S':'C'}}</button></aside>
  <aside class="library" v-show="left"><div class="panel-heading">节点库 <small>{{palette.length}}</small></div><div class="library-search"><input aria-label="搜索节点" placeholder="搜索节点…" v-model="search"></div><div class="section-label">受检节点 · 固定目录</div><div class="library-list"><button v-for="[tid,label] in palette" :key="tid" class="library-node" :data-type="tid" draggable="true" @dragstart="e=>e.dataTransfer.setData('application/aos-node',tid)" @click="add(tid)"><span class="lib-symbol">{{tid.startsWith('tool.')?'⌁':tid==='p07.model'?'◇':'▤'}}</span><div><strong>{{label}}</strong><small>{{tid}}</small></div><span class="add-plus">+</span></button></div><div class="library-footer"><label>离线 SDK 场景<select aria-label="SDK场景" v-model="modelChoice" @change="chooseModel"><option v-for="(doc,tid) in modelSamples" :value="tid">{{labels[tid]}}</option></select></label><label>项目内文档<input aria-label="文档名称" v-model="name" maxlength="48"></label><button @click="reset(false)" :disabled="!catalog">载入合成示例</button><button @click="reset(true)" :disabled="!catalog">载入审批示例</button><div class="file-tools"><button @click="download" :disabled="!base">导出</button><button @click="fileInput.click()">导入</button></div><input hidden type="file" accept=".json" ref="fileInput" @change="importFile"></div></aside>
  <div v-show="left" class="splitter left-split" role="separator" aria-label="调整节点库宽度" tabindex="0" @pointerdown="resize('left',$event)" @keydown="resizeKey('left',$event)" @dblclick="lw=220;prefs()"/>
  <section class="editor" aria-label="工作流画布" @drop="drop" @dragover.prevent>
   <div class="canvas-head"><span>工作流 <small>{{nodes.length}} 节点 · {{edges.length}} 连线</small></span><div><button @click="undo" :disabled="!history.length" title="撤销 Ctrl+Z">↶</button><button @click="redo" :disabled="!future.length" title="重做 Ctrl+Shift+Z">↷</button><button @click="duplicate" :disabled="!selectedCount" title="复制 Ctrl+D">复制</button><button @click="remove" :disabled="!selectedCount&&!edges.some(e=>e.selected)" title="Delete">删除</button></div></div>
   <VueFlow @nodes-initialized="()=>{if(pendingFit){fitView({padding:.06,maxZoom:1});pendingFit=false}}" v-model:nodes="nodes" v-model:edges="edges"  :min-zoom=".25" :max-zoom="2" :is-valid-connection="validConnection" :delete-key-code="null" :selection-key-code="'Shift'" :multi-selection-key-code="'Shift'" :pan-on-drag="[1,2]" :pan-activation-key-code="'Space'" :zoom-activation-key-code="'Control'" :zoom-on-scroll="false" :zoom-on-pinch="true" @connect="connect" @node-drag-start="capture" @node-drag-stop="saved=false" :snap-to-grid="true" :snap-grid="[8,8]">
    <template #node-aos="props"><FlowNode v-bind="props"/></template><Background pattern-color="#2c3540" :gap="20" :size="1"/>
   </VueFlow>
   <div class="canvas-footer"><span>{{selectedCount?selectedCount+' 个节点已选择':'Space 平移 · Ctrl+滚轮缩放'}}</span><div><button @click="zoomOut" aria-label="缩小">−</button><span>{{Math.round(viewport.zoom*100)}}%</span><button @click="zoomIn" aria-label="放大">+</button><button @click="fitView({padding:.06,maxZoom:1})" title="Home">适应画布</button></div></div>
  </section>
  <div v-show="right" class="splitter right-split" role="separator" aria-label="调整检查器宽度" tabindex="0" @pointerdown="resize('right',$event)" @keydown="resizeKey('right',$event)" @dblclick="rw=300;prefs()"/>
  <aside class="inspector" v-show="right"><div class="panel-heading">属性检查器 <small>{{selectedCount>1?'多选 '+selectedCount:'节点'}}</small></div><div class="inspector-body" v-if="selected"><div class="selected-type">{{labels[selected.typeId]||'未知节点'}}</div><code>{{selected.typeId}} @ {{selected.typeVersion}}</code><label class="id-field">实例标识 <span>{{selected.id}}</span></label><div v-if="!def(selected.typeId,selected.typeVersion)" class="local-error">未安装兼容节点描述。原始定义将保留，不能执行。</div><template v-if="selectedCount===1"><h3>参数</h3><p v-if="selected.typeId.startsWith('p08.')" class="muted" data-testid="model-capability">离线 HTTP · 自有服务，不是模型推理。仅显示本节点能力 Schema 支持的参数；不支持流式、工具调用及推理参数。</p><label class="schema-field" v-for="[key,s] in fields" :key="selected.id+key"><span>{{s.title||key}} <small v-if="def(selected.typeId)?.configSchema.required?.includes(key)">*</small></span><input v-if="s.type==='boolean'" type="checkbox" :checked="selected.config[key]" :aria-label="key" @change="setField(key,s,$event)"><input v-else-if="s.const!==undefined" :value="s.const" readonly :aria-label="key"><select v-else-if="s.enum" :value="selected.config[key]" :aria-label="key" @change="setField(key,s,$event)"><option v-for="v in s.enum" :value="v">{{v}}</option></select><textarea v-else-if="s.type==='string'" rows="3" :value="selected.config[key]" :aria-label="key" @change="setField(key,s,$event)"/><input v-else-if="['number','integer'].includes(s.type)" type="number" :value="selected.config[key]" :aria-label="key" :min="s.minimum" :max="s.maximum" :step="s.type==='integer'?1:.1" @change="setField(key,s,$event)"><span v-else class="local-error">此 Schema 尚无编辑控件，保留原值。</span><small v-if="s.minimum!==undefined">{{s.minimum}}–{{s.maximum??'∞'}} · {{s.type}}</small></label><p class="muted" v-if="!fields.length">此节点没有可编辑参数。</p></template><p v-else class="muted">多选仅支持移动、复制和删除。逐节点配置参数。</p><h3>连接端口</h3><div v-for="p in ports(selected)" class="port-inspector" :key="p.id"><span>{{p.direction==='input'?'←':'→'}} {{p.id}}</span><code>{{p.type.schemaRef||p.type.name}}</code><button v-if="p.direction==='output'" @click="picking={source:selected.id,sourceHandle:p.id}">作为起点</button><button v-else-if="picking" @click="connect({...picking,target:selected.id,targetHandle:p.id})">连接至此</button></div><p v-if="picking" class="muted">起点 {{picking.source}} / {{picking.sourceHandle}} · Esc 取消</p><h3>运行准入 · 草稿</h3><label class="schema-field">运行 Token 上限<input aria-label="runMaxTokens" type="number" :value="base.executionPolicy.budget.maxTokens" @change="setBudget('maxTokens',$event)"></label><label class="schema-field">运行费用上限（合成分）<input aria-label="runMaxCostMinor" type="number" :value="base.executionPolicy.budget.maxCostMinor" @change="setBudget('maxCostMinor',$event)"></label><label class="schema-field">最大并发<input aria-label="runConcurrency" type="number" min="1" max="8" :value="base.executionPolicy.concurrencyLimit" @change="setBudget('concurrencyLimit',$event)"></label><h3>本次运行 · 固定修订</h3><div v-if="snapshot?.nodes['main/'+selected.id]" class="node-record"><strong>{{labelState(snapshot.nodes['main/'+selected.id].state)}}</strong><code>{{snapshot.nodes['main/'+selected.id].phase}}</code><pre>{{JSON.stringify(Object.fromEntries(Object.entries(snapshot.nodes['main/'+selected.id].outputs||{}).map(([k,v])=>[k,v.payload])),null,2)}}</pre><p v-if="snapshot.nodes['main/'+selected.id].error" class="local-error">{{snapshot.nodes['main/'+selected.id].error.code}}</p></div><p class="muted" v-else>尚无该节点运行记录。</p></div><div v-else class="empty-inspector"><span>◇</span><strong>选择节点以检查</strong><p>参数、类型端口和已确认的运行输出在此显示。</p><hr><p>执行环境</p><strong>Windows · 可信合成服务</strong><p>模型 SDK 连接自有离线 HTTP 服务。OpenAI / Anthropic 真实模型未配置、未授权。MCP 继续使用独立 stdio 服务。</p></div></aside>
  <div v-show="bottom" class="splitter bottom-split" role="separator" aria-label="调整执行区高度" tabindex="0" @pointerdown="resize('bottom',$event)" @keydown="resizeKey('bottom',$event)" @dblclick="bh=180;prefs()"/>
  <section class="debug" v-show="bottom"><nav class="debug-tabs"><button v-for="[id,title] in [['overview','运行结果'],['problems','问题'],['events','事件'],['raw','原始记录']]" :class="{active:tab===id}" @click="tab=id">{{title}} <small v-if="id==='events'">{{events.length}}</small><small v-if="id==='problems'">{{problems.length+(error?1:0)}}</small></button><div class="spacer"/><code v-if="snapshot">{{snapshot.runId.slice(0,20)}} · seq {{snapshot.seq}}</code><span v-else>尚未创建运行</span></nav><div class="debug-body" v-if="tab==='overview'"><template v-if="approvals.length"><article class="approval" v-for="a in approvals" :key="a.id"><div><strong>◇ 批准本次合成操作？</strong><p>{{a.key}} · {{snapshot.nodes[a.key]?.operationId}}</p><pre>{{JSON.stringify(a.action?.inputs||'正在向 C1 核对固定动作…',null,2)}}</pre><code>{{a.fingerprint}}</code><p>有效至 {{new Date(a.expiresAt*1000).toLocaleTimeString()}}</p></div><button @click="decide(a,false)" :disabled="busy">拒绝</button><button class="primary" @click="decide(a,true)" :disabled="busy||!a.verified">批准本次操作</button></article></template><template v-else-if="snapshot"><div class="run-summary"><strong :class="snapshot.state">{{labelState(snapshot.state)}}</strong><span>运行修订 {{snapshot.workflowRevision}}</span><span>当前草稿 {{base?.version.revision}}</span></div><div class="run-summary" data-testid="model-usage"><span>已确认 {{snapshot.usage.spentTokens}} Token</span><span>预留 / 待核实 {{snapshot.usage.reservedTokens}} Token</span><span>合成估算 {{snapshot.modelCosts?.estimatedMinor??0}} 分 · 预留 {{snapshot.modelCosts?.reservedMinor??0}} 分</span><span>非供应商账单</span></div><pre class="result" data-testid="output">{{result!==undefined?JSON.stringify(result,null,2):snapshot.state==='running'?'正在等待实际输出…':snapshot.state==='failed'?'运行失败，请查看问题。':'暂无已确认的输出。'}}</pre></template><div class="empty-result" v-if="!snapshot"><span>⌁</span><div><strong>从画布到真实执行</strong><p>{{notice}}</p></div><button @click="run" :disabled="!canRun">运行合成工作流 →</button></div></div><div class="debug-body" v-else-if="tab==='problems'"><p v-if="error" class="local-error">{{error}}</p><div v-for="p in problems" class="local-error">{{p.id}} · {{p.message}}</div><p v-if="!error&&!problems.length" class="muted">暂无已报告的问题。</p></div><div class="debug-body event-list" v-else-if="tab==='events'"><div v-for="e in events" :key="e.seq"><code>{{e.seq}}</code><strong>{{e.kind}}</strong><span>{{e.key||e.runId}}</span></div></div><pre v-else class="debug-body raw">{{snapshot?JSON.stringify(snapshot,null,2):'无运行记录'}}</pre></section>
 </div>
 <footer class="statusbar"><span :class="{'connection-error':connection!=='C1 已连接'}">● {{connection}}</span><span>{{notice}}</span><div class="spacer"/><span>{{base?.version.revision}}</span><span>L1 定义 / L2 依赖执行</span></footer>
</main>
</template>
